}
AMMESSI = ["00 - Indice Generale ITS (MOC)","00 - Indice AWS (MOC)","01 - Fondamenti di networking","02 - Reti Wi-Fi e VPN","03 - Simulazione dei protocolli di rete","04 - Fondamenti di cloud computing","05 - Classificazione dei servizi cloud","06 - Immagini, container e registri","07 - Dockerfile, networking e Kubernetes","99 - Glossario, Comandi e Cheat Sheet AWS"]
LINGUAGGI = {"powershell","bash","dockerfile","yaml","python","json","http","text","mermaid"}
SENSIBILI = ["CSP-2527","edu-its","DC-ITS","228D7269","Tarallo","luca.tarallo","LUCA~1"]
testi = {n: open(os.path.join(CARTELLA, n + ".md"), encoding="utf-8").read() for n in FILES}
titoli = {}
for n, t in testi.items():
