    fm = f"---\ntags: [dispensa, its, aws]\nmodulo: \"{num}\"\nstato: da-ripassare\n---\n"
    if not t.startswith(fm): errore(n, "frontmatter non conforme")
    if righe[5] != nav: errore(n, f"nav in alto diversa: {righe[5]!r}")
    ultime = [r for r in righe if r.strip()]
    if ultime[-1] != nav: errore(n, f"nav in fondo diversa: {ultime[-1]!r}")
    if righe[7] != h1: errore(n, f"H1 errato: {righe[7]!r}")
    if sum(1 for r in righe if r.startswith("# ")) != 1: errore(n, "H1 non unico")
    # titoli
    for r in righe:
        m = re.match(r"^(#{2,6})\s+(.*)$", r)
        if m and re.search(r"[#\^\[\]\|:]", m.group(2)): errore(n, f"titolo con carattere vietato: {r}")
