        s = r[2:] if r.startswith("> ") else (r[1:] if r == ">" else r)
        nel_callout = r.startswith(">")
        if re.match(r"^\s*```", s):
            if not in_code:
                lang = s.strip()[3:].strip()
                if lang not in LINGUAGGI: errore(n, f"riga {i}: blocco senza linguaggio ammesso ({lang!r})")
                in_code = True; in_callout_code = nel_callout
            else:
                in_code = False
        elif in_code and in_callout_code and not r.startswith(">"):
            errore(n, f"riga {i}: riga di codice in callout senza '> '")
    if in_code: errore(n, "blocco di codice non chiuso")
    # callout
    for i, r in enumerate(righe, 1):
        m = re.match(r"^>\s*\[!(\w+)\](-?)\s*(.*)$", r)
