            dest = re.split(r"\\?\|", dentro)[0]
            file_, _, anc = dest.partition("#")
            file_ = file_ or n
            if file_ not in AMMESSI: errore(n, f"riga {i}: link a file non ammesso: {file_}")
            if anc:
