                else:
                    errore(n, f"riga {i}: ancora verso modulo di altro autore: {dest}")
    # struttura H2
    h2 = [re.sub(r"^##\s+", "", r) for r in righe if r.startswith("## ")]
    attesi = ["Mini-exercises", f"Laboratorio {num} — ", "Errori comuni e troubleshooting", "Wrap-up e link suggeriti", "Domande di richiamo"]
    pos = []
    for a in attesi:
        idx = [k for k, h in enumerate(h2) if h.startswith(a)]
        if not idx: errore(n, f"manca H2 {a}"); pos.append(-1)
        else: pos.append(idx[0])
    if pos != sorted(pos): errore(n, f"ordine H2 errato: {pos}")
    print("  H2:", " | ".join(h2))
    # H3 del laboratorio
    for h in ["Obiettivo e prerequisiti", "Evidenze e come leggerle", "Cleanup", "Consegna"]:
        if h not in titoli[n]: errore(n, f"manca H3 {h}")
    # domande e risposte
    sez = t.split("## Domande di richiamo", 1)[1]
    dom, risp = sez.split("> [!success]- Risposte", 1)
    nd = len(re.findall(r"^\d+\. ", dom, re.M)); nr = len(re.findall(r"^> \d+\. ", risp, re.M))
    if not (6 <= nd <= 10) or nd != nr: errore(n, f"domande {nd} / risposte {nr}")
    # fonti per sezione H2
    blocchi = re.split(r"^## ", t, flags=re.M)[1:]
    for b in blocchi:
        nome = b.split("\n", 1)[0]
        if nome.startswith("Domande di richiamo"): continue
        if "*Fonti originali:" not in b: errore(n, f"sezione senza riga fonti: {nome}")
    # dati sensibili
    for s in SENSIBILI:
        if s.lower() in t.lower(): errore(n, f"dato sensibile presente: {s}")
    # mermaid: controlli di base
    for blocco in re.findall(r"```mermaid\n(.*?)```", t, re.S):
        for riga in blocco.split("\n"):
            if "subgraph" in riga: errore(n, f"mermaid con subgraph: {riga.strip()}")
            fuori = re.sub(r'"[^"]*"', '', riga)
            if re.search(r"[;#]", fuori): errore(n, f"mermaid con carattere speciale fuori dalle virgolette: {riga.strip()}")
print("PROBLEMI TOTALI:", problemi)
EOF
