# Controlla che ogni tabella Markdown abbia lo stesso numero di celle su tutte le righe
import sys, os

CARTELLA = sys.argv[1]
NOMI = ["01 - Fondamenti di networking", "02 - Reti Wi-Fi e VPN", "03 - Simulazione dei protocolli di rete"]


def conta_celle(riga):
    """Conta le celle ignorando le barre protette da backslash e quelle dentro il codice inline."""
    celle, in_codice, prec = 0, False, ""
    for ch in riga.strip():
        if ch == "`":
            in_codice = not in_codice
        elif ch == "|" and not in_codice and prec != "\\":
            celle += 1
        prec = ch
    return celle - 1


problemi = 0
for nome in NOMI:
    righe = open(os.path.join(CARTELLA, nome + ".md"), encoding="utf-8").read().split("\n")
    blocco = []
    for i, r in enumerate(righe + [""], 1):
        if r.lstrip().startswith("|"):
            blocco.append((i, r))
        else:
            if blocco:
                attese = conta_celle(blocco[0][1])
                for n, riga in blocco:
                    if conta_celle(riga) != attese:
                        problemi += 1
                        print(f"[{nome[:2]}] riga {n}: {conta_celle(riga)} celle invece di {attese}: {riga[:120]}")
                if len(blocco) < 2 or set(blocco[1][1].replace("|", "").replace(" ", "")) - set("-:"):
                    problemi += 1
                    print(f"[{nome[:2]}] riga {blocco[0][0]}: manca la riga di separazione")
            blocco = []
print("PROBLEMI TABELLE:", problemi)

